import numpy as np, itertools
rng = np.random.default_rng(0)

def nash_eq_count_gm(A, B, tol=1e-7):
    m, n = A.shape
    eqs = []
    for k in range(1, min(m,n)+1):
        for S in itertools.combinations(range(m), k):
            for T in itertools.combinations(range(n), k):
                N = 2*k+2
                M = np.zeros((N,N)); b = np.zeros(N)
                r=0
                for i in S[1:]:
                    for idx,j in enumerate(T): M[r, k+idx] = A[i,j]-A[S[0],j]
                    M[r, 2*k] = -1.0
                    r+=1
                for idx,j in enumerate(T): M[r, k+idx]=1.0
                b[r]=1.0; r+=1
                for j in T[1:]:
                    for idx,i in enumerate(S): M[r, idx] = B[i,j]-B[i,T[0]]
                    M[r, 2*k+1] = -1.0
                    r+=1
                for idx,i in enumerate(S): M[r, idx]=1.0
                b[r]=1.0; r+=1
                try:
                    sol = np.linalg.solve(M,b)
                except np.linalg.LinAlgError:
                    continue
                p = sol[:k]; q = sol[k:2*k]; v1=sol[2*k]; v2=sol[2*k+1]
                if np.any(p < -1e-9) or np.any(q < -1e-9):
                    continue
                p = np.clip(p,0,None); q=np.clip(q,0,None)
                p/=p.sum(); q/=q.sum()
                P = np.zeros(m); P[list(S)] = p
                Q = np.zeros(n); Q[list(T)] = q
                br1 = A @ Q; br2 = P @ B
                if abs(br1.max()-v1) < tol and abs(br2.max()-v2) < tol:
                    dup=False
                    for (P2,Q2) in eqs:
                        if np.allclose(P,P2,atol=1e-6) and np.allclose(Q,Q2,atol=1e-6): dup=True;break
                    if not dup: eqs.append((P,Q))
    return len(eqs)

odd=0; tot=0; evens=[]
for t in range(80):
    m = int(rng.integers(2,5)); n = int(rng.integers(2,5))
    A = rng.normal(size=(m,n)); B = rng.normal(size=(m,n))
    c = nash_eq_count_gm(A,B)
    tot+=1
    if c%2==1: odd+=1
    else: evens.append((m,n,c))
print("games sampled:", tot, "odd count:", odd, "even exceptions:", evens)
"}

