from itertools import product

# Define tetromino shapes as sets of (dx,dy) offsets, all rotations/flips
def norm(cells):
    minx=min(c[0] for c in cells); miny=min(c[1] for c in cells)
    return frozenset((x-minx,y-miny) for x,y in cells)

def transforms(cells):
    cur=set(cells); out=set()
    for _ in range(4):
        out.add(norm(cur))
        # reflect
        refl={(x,-y) for x,y in cur}
        out.add(norm(refl))
        cur={(y,-x) for x,y in cur}
    return out

T_shape=[(0,0),(1,0),(2,0),(1,1)]
S_shape=[(0,1),(1,1),(1,0),(2,0)]

T_ors=transforms(T_shape)
S_ors=transforms(S_shape)
print("T orientations:",len(T_ors))
print("S orientations:",len(S_ors))

# weight function f(i) on column i, period 4: f = [1,1,-1,-1] pattern? Try classic: f(i)=1 for i mod4 in {0,1}, -1 for {2,3}
def f(i):
    m=i%4
    return 1 if m in (0,1) else -1

def wsum(shape):
    return sum(f(x) for x,y in shape)

Tsums=sorted(set(wsum(s) for s in T_ors))
Ssums=sorted(set(wsum(s) for s in S_ors))
print("T weight sums:",Tsums)
print("S weight sums:",Ssums)
